using System;using System.IO;using System.Reflection;using IdleRestaurant;using UnityEngine;
public sealed class GapSaveProbe:MonoBehaviour{
 RestaurantApp app;bool done;
 void Update(){if(done)return;if(!app)app=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>();if(!app||app.Game==null)return;var live=app.Game;if(live.TeamCount!=3||live.State.lastRecruitWaves<0||live.TotalWaves()!=live.State.lastRecruitWaves+1)return;done=true;try{app.Save();var store=(SaveStore)typeof(RestaurantApp).GetField("store",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(app);bool recovered;var state=store.Read(out recovered);var restored=new RestaurantGame(app.catalog,state);if(recovered||restored.State.lastRecruitWaves!=live.State.lastRecruitWaves||restored.RecruitServicesRequired!=live.RecruitServicesRequired||restored.CanRecruit(out _)||Math.Abs(restored.State.cash-live.State.cash)>.00001)throw new Exception("Gap save/reload mismatch");File.WriteAllText(Path.GetFullPath("Recordings/FinalGap052/GapSaveRoundtrip.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{utc=DateTime.UtcNow,status="PASS",seconds=live.State.seconds,waves=live.TotalWaves(),lastRecruitWaves=live.State.lastRecruitWaves,requiredServices=live.RecruitServicesRequired,managers=live.TeamCount,scope="Actual live gap after one service saved and read through SaveStore; restored model remains blocked without changing live model"},Newtonsoft.Json.Formatting.Indented));}catch(Exception ex){File.WriteAllText(Path.GetFullPath("Recordings/FinalGap052/GapSaveRoundtrip.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{status="FAIL",error=ex.ToString()}));}Destroy(this);}
 public static void Main(){UnityEngine.Object.FindAnyObjectByType<RestaurantApp>().gameObject.AddComponent<GapSaveProbe>();}
}
